namespace sv_b590487d25724e5583720d92cbd4d574.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service — one instance per circuit (per user).
/// Any component can inject this to read/write theme state.
/// Subscribers re-render via the OnChange event.
/// </summary>
public class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Components subscribe to this to trigger StateHasChanged when theme changes.
    /// </summary>
    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<span class="theme-indicator" style="color: @ThemeService.AccentColor;">
    @GetIcon() @ThemeService.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += OnThemeChanged;
    }

    private void OnThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetIcon() => ThemeService.Theme switch
    {
        ThemeMode.Dark => "🌙",
        ThemeMode.Light => "☀️",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= OnThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" @bind="SelectedTheme">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <option value="@mode">@mode</option>
        }
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color"
           @bind="SelectedColor" @bind:event="oninput" />
</div>

<p>
    Current: <strong style="color: @ThemeService.AccentColor;">@ThemeService.Theme</strong>
</p>

@code {
    private ThemeMode SelectedTheme
    {
        get => ThemeService.Theme;
        set => ThemeService.Theme = value;
    }

    private string SelectedColor
    {
        get => ThemeService.AccentColor;
        set => ThemeService.AccentColor = value;
    }

    protected override void OnInitialized()
    {
        ThemeService.OnChange += OnThemeChanged;
    }

    private void OnThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= OnThemeChanged;
    }
}

